"use strict";(self.webpackChunkgrc=self.webpackChunkgrc||[]).push([[46977],{96331:e=>{e.exports=JSON.parse('[{"title":"Characterizing Dataflow for I/O-Aware Scheduling in HPC Workflows","authors":["M. Tang","L. Guo","A. Kougkas","X.-H. Sun","N. R. Tallent"],"venue":"40th IEEE International Parallel & Distributed Processing Symposium (IPDPS 2026)","type":"Conference","date":"May, 2026","month":5,"year":2026,"tags":["HPC Analysis","I/O","Workflow Optimization","Data Analytics","Performance Measurement"],"links":{"pdf":"http://cs.iit.edu/~scs/assets/files/tang2026characterizing.pdf","bibtex":"http://cs.iit.edu/~scs/assets/files/tang2026characterizing.bib","citation":"http://cs.iit.edu/~scs/assets/files/tang2026characterizing.txt"},"doi":"10.1109/IPDPS65963.2026.00076","abstract":"Scientific discoveries are increasingly facilitated by data-driven workflows executed in HPC environments, where complex task-to-data exchange patterns cause bottlenecks in shared storage. Existing I/O-aware scheduling techniques use application-oriented metrics that primarily focus on individual task characteristics, leaving workflow-level dataflow behaviors\u2014such as file reuse and producer\u2013consumer I/O patterns\u2014underexplored despite their importance for effective orchestration. This paper presents a workflow-centric methodology to characterize and analyze I/O using workflow-specific patterns and metrics. By correlating workflow structures (e.g., task composition, execution order, and producer\u2013consumer relationships) with I/O metrics (e.g., access type, operation count, and data size), we gain deeper insight into workflow I/O dynamics. We evaluate our approach on six diverse HPC workflows, covering 3,500 task instances and 1,387 unique files, with a total I/O volume of 1.5 TB. This analysis uncovers a spectrum of behaviors related to file reuse, data exchange, and task-level I/O heterogeneity. These insights reveal new opportunities and research directions for I/O-aware scheduling, supporting smarter task placement, data movement, and storage selection in HPC.","slug":"tang-2026-dataflow-workflow-b4e1"},{"title":"The Hidden Cost of Storage Mismatches: Why Faster I/O Per Task Can Slow Down Entire Workflows","authors":["M. Tang","L. Guo","N. R. Tallent","A. Kougkas","X.-H. Sun"],"venue":"13th Greater Chicago Area Systems Research Workshop (GCASR 2026)","type":"Poster","date":"May, 2026","month":5,"year":2026,"tags":["HPC Analysis","I/O","Workflow Optimization","Data Analytics","Performance Measurement"],"links":{"poster":"http://cs.iit.edu/~scs/assets/files/tang2026storage.pdf","bibtex":"http://cs.iit.edu/~scs/assets/files/tang2026storage.bib","citation":"http://cs.iit.edu/~scs/assets/files/tang2026storage.txt"},"abstract":"Data-intensive scientific workflows in high-performance computing exchange intermediate data between pipeline stages through shared storage such as parallel file systems, local SSDs, and burst buffers. Existing workflow schedulers select storage to maximize individual task throughput, implicitly assuming that faster I/O per task yields faster end-to-end execution. We show this assumption is wrong. We present an empirical study across two scientific workflows\u2014genomics and climate tracking\u2014on a production HPC cluster. By benchmarking storage systems across operation types, transfer sizes, parallelism levels, and data volumes, we uncover two non-obvious findings. First, data movement between storage tiers scales fundamentally differently from read and write operations: copy throughput plateaus or degrades at parallelism levels where reads and writes continue to scale, making cross-tier staging costs unpredictable from standard I/O benchmarks. Second, producer-consumer task pairs can exhibit performance inversion\u2014configurations that maximize throughput for individual tasks introduce costly inter-stage data movement that increases total workflow time by up to 6.8x compared to storage-aware alternatives. Across both workflows, I/O accounts for 42\u201398% of total execution time, yet the penalty from storage mismatches between dependent tasks can exceed the compute cost of the tasks themselves. These patterns hold across fundamentally different access profiles, from large sequential transfers to metadata-heavy many-small-file workloads. Our results demonstrate that producer-consumer data dependencies must be treated as first-class constraints in workflow scheduling.","slug":"tang-2026-storage-mismatches-7f3d"},{"title":"Quantifying AWS S3 I/O Performance Boundaries Using the Roofline Model","authors":["M. Tang","Z. Zhu","L. Guo","J. G. Bandy","T. Carlson","S. Neuwirth","A. Kougkas","X.-H. Sun","N. R. Tallent"],"venue":"The 10th International Parallel Data Systems Workshop (PDSW\'25)","type":"Workshop","date":"November, 2025","month":11,"year":2025,"tags":["I/O","Cloud Storage","AWS S3","Roofline Model","Performance Analysis"],"links":{"bibtex":"http://cs.iit.edu/~scs/assets/files/tang2025roofline.bib","citation":"http://cs.iit.edu/~scs/assets/files/tang2025roofline.txt","pdf":"http://cs.iit.edu/~scs/assets/files/tang2025roofline.pdf"},"abstract":"High-performance computing facilities increasingly form hybrid environments that integrate cloud services. To avoid cumbersome network transfers when sharing data, a new class of storage gateways map a subset of facility storage to a cloud counterpart and automatically manage data mirroring. However, the performance characteristics of accessing AWS\'s S3 from HPC systems using different methods and patterns remains poorly understood. This paper presents a roofline-based analysis of three S3 integration approaches: NFS-mounted AWS Storage Gateway, data migration through Storage Gateway, and direct S3 API transfers. We extend I/O roofline modeling to characterize operational intensity and bandwidth ceilings across varying data sizes and access patterns. Our experimental evaluation demonstrates significant performance differences between access methods, with POSIX I/O on NFS Storage Gateway achieving up to 6.4\xd7 higher bandwidth than other approaches for large transfers. The roofline analysis reveals distinct characteristics for each method, enabling informed selection of S3 integration strategies.","slug":"tang-2025-s3-roofline-c7bd"},{"title":"Analyzing I/O Patterns and Dataflow in HPC Workflows","authors":["M. Tang","L. Guo","N. Tallent","A. Kougkas","X.-H. Sun"],"venue":"The 37h International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Poster","date":"June, 2025","month":6,"tags":["HPC Analysis","I/O","Workflow Optimization","Data Analytics","Performance Measurement"],"links":{"poster":"http://cs.iit.edu/~scs/assets/files/tang2025ioworkflow_poster.pdf","bibtex":"http://cs.iit.edu/~scs/assets/files/tang2025ioworkflow.bib","citation":"http://cs.iit.edu/~scs/assets/files/tang2025ioworkflow.txt"},"slug":"tang-2025-ioworkflows-a9f3"},{"abstract":"The combination of ever-growing scientific datasets\\nand distributed workflow complexity creates I/O performance\\nbottlenecks due to data volume, velocity, and variety. Although\\nthe increasing use of descriptive data formats (e.g., HDF5,\\nnetCDF) helps organize these datasets, it also introduces obscure\\nbottlenecks due to the need to translate high-level operations\\ninto file addresses and then into low-level I/O operations. To\\naddress this challenge, we introduce DaYu, a method and toolset\\nfor analyzing (a) semantic relationships between logical datasets\\nand file addresses, (b) how dataset operations translate into\\nI/O, and (c) the combination across entire workflows. DaYu\'s\\nanalysis and visualization enable the identification of critical\\nbottlenecks and the reasoning about remediation. We describe\\nour methodology and propose optimization guidelines. Evaluation\\non scientific workflows demonstrates up to a 3.7x performance\\nimprovement in I/O time for obscure bottlenecks. The time and\\nstorage overhead for DaYu\'s time-ordered data are typically\\nunder 0.2% of runtime and 0.25% of data volume, respectively.","authors":["M. Tang","J. Cernuda","J. Ye","L. Guo","N. Tallent","A. Kougkas","X.-H. Sun"],"date":"September, 2024","doi":"10.1109/cluster59578.2024.00038","links":{"bibtex":"http://cs.iit.edu/~scs/assets/files/tang2024dayu.bib","citation":"http://cs.iit.edu/~scs/assets/files/tang2024dayu.txt","pdf":"http://cs.iit.edu/~scs/assets/files/tang2024dayu.pdf"},"month":9,"slug":"tang-2024-dayu-f286","tags":["Data Analytics","Modeling","Performance Measurement","Tools","Workflow Optimization"],"title":"DaYu: Optimizing Distributed Scientific Workflows by Decoding Dataflow Semantics and Dynamics","type":"Conference","venue":"2024 IEEE International Conference on Cluster Computing (CLUSTER\'24)","year":2024},{"abstract":"A critical performance challenge in distributed scientific workflows\\nis coordinating tasks and data flows on distributed resources. To\\nguide these decisions, this paper introduces data flow lifecycle anal-\\nysis. Workflows are commonly represented using directed acyclic\\ngraphs (DAGs). Data flow lifecycles (DFL) enrich task DAGs with\\ndata objects and properties that describe data flow and how tasks\\ninteract with that flow. Lifecycles enable analysis from several\\nimportant perspectives: task, data, and data flow. We describe rep-\\nresentation, measurement, analysis, visualization, and opportunity\\nidentification for DFLs. Our measurement is both distributed and\\nscalable, using space that is constant per data file. We use lifecycles\\nand opportunity analysis to reason about improved task placement\\nand reduced data movement for five scientific workflows with dif-\\nferent characteristics. Case studies show improvements of 15x, 1.9\xd7,\\nand 10-30x. Our work is implemented in the DataLife tool.","authors":["H. Lee","L. Guo","M. Tang","J. Firoz","N. Tallent","A. Kougkas","X.-H. Sun"],"date":"November, 2023","links":{"bibtex":"http://cs.iit.edu/~scs/assets/files/lee2023data.bib","citation":"http://cs.iit.edu/~scs/assets/files/lee2023data.txt","pdf":"http://cs.iit.edu/~scs/assets/files/lee2023data.pdf"},"month":11,"slug":"lee-2023-data-lifecycles-c393","tags":["Data Analytics","Performance Measurement","Modeling","Tools"],"title":"Data Lifecycles: Optimizing Workflow Task & Data Coordination","type":"Conference","venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'23), November 12-17, 2023","year":2023},{"title":"Optimizing Workflow Performance by Elucidating Semantic Data Flow","authors":["M. Tang","N. Tallent","A. Kougkas","X.-H. Sun"],"venue":"The International Conference for High Performance Computing, Networking, Storage and Analysis (SC\'23)","type":"Poster","date":"November, 2023","month":11,"tags":["HPC Analysis","I/O","Workflow Optimization","Data Analytics","Performance Measurement"],"links":{"poster":"http://cs.iit.edu/~scs/assets/files/tang2023semantic_poster.pdf","bibtex":"http://cs.iit.edu/~scs/assets/files/tang2023semantic.bib","citation":"http://cs.iit.edu/~scs/assets/files/tang2023semantic.txt"},"slug":"tang-2023-semantic-workflow-e12d"},{"authors":["I. Yildirim","M. Tang","A. Kougkas","X.-H. Sun"],"date":"November, 2021","links":{"bibtex":"http://cs.iit.edu/~scs/assets/files/yildirim2021containers_poster.bib","citation":"http://cs.iit.edu/~scs/assets/files/yildirim2021containers_poster.txt","extended abstract":"http://cs.iit.edu/~scs/assets/files/yildirim2021containers_abstract.pdf","poster":"http://cs.iit.edu/~scs/assets/files/yildirim2021containers_poster.pdf"},"month":11,"slug":"yildirim-2021-performance-analysis-f217","tags":["HPC","Singularity","Containers","Benchmarking"],"title":"Performance Analysis of Containerized OrangeFS in HPC Environment","type":"Poster","venue":"The 2021 International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'21), November 14\u201319, 2021","year":2021}]')}}]);